     1→#!/usr/bin/env node
     2→import { run } from "./index";
     3→import { showStatus } from "./utils/status";
     4→import { executeCodeCommand } from "./utils/codeCommand";
     5→import { parseStatusLineData, type StatusLineInput } from "./utils/statusline";
     6→import {
     7→  cleanupPidFile,
     8→  isServiceRunning,
     9→  getServiceInfo,
    10→} from "./utils/processCheck";
    11→import { runModelSelector } from "./utils/modelSelector"; // ADD THIS LINE
    12→import { activateCommand } from "./utils/activateCommand";
    13→import { version } from "../package.json";
    14→import { spawn, exec } from "child_process";
    15→import { PID_FILE, REFERENCE_COUNT_FILE } from "./constants";
    16→import fs, { existsSync, readFileSync } from "fs";
    17→import { join } from "path";
    18→
    19→const command = process.argv[2];
    20→
    21→const HELP_TEXT = `
    22→Usage: ccr [command]
    23→
    24→Commands:
    25→  start         Start server
    26→  stop          Stop server
    27→  restart       Restart server
    28→  status        Show server status
    29→  statusline    Integrated statusline
    30→  code          Execute claude command
    31→  model         Interactive model selection and configuration
    32→  activate      Output environment variables for shell integration
    33→  ui            Open the web UI in browser
    34→  -v, version   Show version information
    35→  -h, help      Show help information
    36→
    37→Example:
    38→  ccr start
    39→  ccr code "Write a Hello World"
    40→  ccr model
    41→  eval "$(ccr activate)"  # Set environment variables globally
    42→  ccr ui
    43→`;
    44→
    45→async function waitForService(
    46→  timeout = 10000,
    47→  initialDelay = 1000
    48→): Promise<boolean> {
    49→  // Wait for an initial period to let the service initialize
    50→  await new Promise((resolve) => setTimeout(resolve, initialDelay));
    51→
    52→  const startTime = Date.now();
    53→  while (Date.now() - startTime < timeout) {
    54→    const isRunning = await isServiceRunning()
    55→    if (isRunning) {
    56→      // Wait for an additional short period to ensure service is fully ready
    57→      await new Promise((resolve) => setTimeout(resolve, 500));
    58→      return true;
    59→    }
    60→    await new Promise((resolve) => setTimeout(resolve, 100));
    61→  }
    62→  return false;
    63→}
    64→
    65→async function main() {
    66→  const isRunning = await isServiceRunning()
    67→  switch (command) {
    68→    case "start":
    69→      run();
    70→      break;
    71→    case "stop":
    72→      try {
    73→        const pid = parseInt(readFileSync(PID_FILE, "utf-8"));
    74→        process.kill(pid);
    75→        cleanupPidFile();
    76→        if (existsSync(REFERENCE_COUNT_FILE)) {
    77→          try {
    78→            fs.unlinkSync(REFERENCE_COUNT_FILE);
    79→          } catch (e) {
    80→            // Ignore cleanup errors
    81→          }
    82→        }
    83→        console.log(
    84→          "claude code router service has been successfully stopped."
    85→        );
    86→      } catch (e) {
    87→        console.log(
    88→          "Failed to stop the service. It may have already been stopped."
    89→        );
    90→        cleanupPidFile();
    91→      }
    92→      break;
    93→    case "status":
    94→      await showStatus();
    95→      break;
    96→    case "statusline":
    97→      // 从stdin读取JSON输入
    98→      let inputData = "";
    99→      process.stdin.setEncoding("utf-8");
   100→      process.stdin.on("readable", () => {
   101→        let chunk;
   102→        while ((chunk = process.stdin.read()) !== null) {
   103→          inputData += chunk;
   104→        }
   105→      });
   106→
   107→      process.stdin.on("end", async () => {
   108→        try {
   109→          const input: StatusLineInput = JSON.parse(inputData);
   110→          const statusLine = await parseStatusLineData(input);
   111→          console.log(statusLine);
   112→        } catch (error) {
   113→          console.error("Error parsing status line data:", error);
   114→          process.exit(1);
   115→        }
   116→      });
   117→      break;
   118→    // ADD THIS CASE
   119→    case "model":
   120→      await runModelSelector();
   121→      break;
   122→    case "activate":
   123→    case "env":
   124→      await activateCommand();
   125→      break;
   126→    case "code":
   127→      if (!isRunning) {
   128→        console.log("Service not running, starting service...");
   129→        const cliPath = join(__dirname, "cli.js");
   130→        const startProcess = spawn("node", [cliPath, "start"], {
   131→          detached: true,
   132→          stdio: "ignore",
   133→        });
   134→
   135→        // let errorMessage = "";
   136→        // startProcess.stderr?.on("data", (data) => {
   137→        //   errorMessage += data.toString();
   138→        // });
   139→
   140→        startProcess.on("error", (error) => {
   141→          console.error("Failed to start service:", error.message);
   142→          process.exit(1);
   143→        });
   144→
   145→        // startProcess.on("close", (code) => {
   146→        //   if (code !== 0 && errorMessage) {
   147→        //     console.error("Failed to start service:", errorMessage.trim());
   148→        //     process.exit(1);
   149→        //   }
   150→        // });
   151→
   152→        startProcess.unref();
   153→
   154→        if (await waitForService()) {
   155→          // Join all code arguments into a single string to preserve spaces within quotes
   156→          const codeArgs = process.argv.slice(3);
   157→          executeCodeCommand(codeArgs);
   158→        } else {
   159→          console.error(
   160→            "Service startup timeout, please manually run `ccr start` to start the service"
   161→          );
   162→          process.exit(1);
   163→        }
   164→      } else {
   165→        // Join all code arguments into a single string to preserve spaces within quotes
   166→        const codeArgs = process.argv.slice(3);
   167→        executeCodeCommand(codeArgs);
   168→      }
   169→      break;
   170→    case "ui":
   171→      // Check if service is running
   172→      if (!isRunning) {
   173→        console.log("Service not running, starting service...");
   174→        const cliPath = join(__dirname, "cli.js");
   175→        const startProcess = spawn("node", [cliPath, "start"], {
   176→          detached: true,
   177→          stdio: "ignore",
   178→        });
   179→
   180→        startProcess.on("error", (error) => {
   181→          console.error("Failed to start service:", error.message);
   182→          process.exit(1);
   183→        });
   184→
   185→        startProcess.unref();
   186→
   187→        if (!(await waitForService())) {
   188→          // If service startup fails, try to start with default config
   189→          console.log(
   190→            "Service startup timeout, trying to start with default configuration..."
   191→          );
   192→          const {
   193→            initDir,
   194→            writeConfigFile,
   195→            backupConfigFile,
   196→          } = require("./utils");
   197→
   198→          try {
   199→            // Initialize directories
   200→            await initDir();
   201→
   202→            // Backup existing config file if it exists
   203→            const backupPath = await backupConfigFile();
   204→            if (backupPath) {
   205→              console.log(
   206→                `Backed up existing configuration file to ${backupPath}`
   207→              );
   208→            }
   209→
   210→            // Create a minimal default config file
   211→            await writeConfigFile({
   212→              PORT: 3456,
   213→              Providers: [],
   214→              Router: {},
   215→            });
   216→            console.log(
   217→              "Created minimal default configuration file at ~/.claude-code-router/config.json"
   218→            );
   219→            console.log(
   220→              "Please edit this file with your actual configuration."
   221→            );
   222→
   223→            // Try starting the service again
   224→            const restartProcess = spawn("node", [cliPath, "start"], {
   225→              detached: true,
   226→              stdio: "ignore",
   227→            });
   228→
   229→            restartProcess.on("error", (error) => {
   230→              console.error(
   231→                "Failed to start service with default config:",
   232→                error.message
   233→              );
   234→              process.exit(1);
   235→            });
   236→
   237→            restartProcess.unref();
   238→
   239→            if (!(await waitForService(15000))) {
   240→              // Wait a bit longer for the first start
   241→              console.error(
   242→                "Service startup still failing. Please manually run `ccr start` to start the service and check the logs."
   243→              );
   244→              process.exit(1);
   245→            }
   246→          } catch (error: any) {
   247→            console.error(
   248→              "Failed to create default configuration:",
   249→              error.message
   250→            );
   251→            process.exit(1);
   252→          }
   253→        }
   254→      }
   255→
   256→      // Get service info and open UI
   257→      const serviceInfo = await getServiceInfo();
   258→
   259→      // Add temporary API key as URL parameter if successfully generated
   260→      const uiUrl = `${serviceInfo.endpoint}/ui/`;
   261→
   262→      console.log(`Opening UI at ${uiUrl}`);
   263→
   264→      // Open URL in browser based on platform
   265→      const platform = process.platform;
   266→      let openCommand = "";
   267→
   268→      if (platform === "win32") {
   269→        // Windows
   270→        openCommand = `start ${uiUrl}`;
   271→      } else if (platform === "darwin") {
   272→        // macOS
   273→        openCommand = `open ${uiUrl}`;
   274→      } else if (platform === "linux") {
   275→        // Linux
   276→        openCommand = `xdg-open ${uiUrl}`;
   277→      } else {
   278→        console.error("Unsupported platform for opening browser");
   279→        process.exit(1);
   280→      }
   281→
   282→      exec(openCommand, (error) => {
   283→        if (error) {
   284→          console.error("Failed to open browser:", error.message);
   285→          process.exit(1);
   286→        }
   287→      });
   288→      break;
   289→    case "-v":
   290→    case "version":
   291→      console.log(`claude-code-router version: ${version}`);
   292→      break;
   293→    case "restart":
   294→      // Stop the service if it's running
   295→      try {
   296→        const pid = parseInt(readFileSync(PID_FILE, "utf-8"));
   297→        process.kill(pid);
   298→        cleanupPidFile();
   299→        if (existsSync(REFERENCE_COUNT_FILE)) {
   300→          try {
   301→            fs.unlinkSync(REFERENCE_COUNT_FILE);
   302→          } catch (e) {
   303→            // Ignore cleanup errors
   304→          }
   305→        }
   306→        console.log("claude code router service has been stopped.");
   307→      } catch (e) {
   308→        console.log("Service was not running or failed to stop.");
   309→        cleanupPidFile();
   310→      }
   311→
   312→      // Start the service again in the background
   313→      console.log("Starting claude code router service...");
   314→      const cliPath = join(__dirname, "cli.js");
   315→      const startProcess = spawn("node", [cliPath, "start"], {
   316→        detached: true,
   317→        stdio: "ignore",
   318→      });
   319→
   320→      startProcess.on("error", (error) => {
   321→        console.error("Failed to start service:", error);
   322→        process.exit(1);
   323→      });
   324→
   325→      startProcess.unref();
   326→      console.log("✅ Service started successfully in the background.");
   327→      break;
   328→    case "-h":
   329→    case "help":
   330→      console.log(HELP_TEXT);
   331→      break;
   332→    default:
   333→      console.log(HELP_TEXT);
   334→      process.exit(1);
   335→  }
   336→}
   337→
   338→main().catch(console.error);

