    13→// Function to interpolate environment variables in config values
    14→const interpolateEnvVars = (obj: any): any => {
    15→  if (typeof obj === "string") {
    16→    // Replace $VAR_NAME or ${VAR_NAME} with environment variable values
    17→    return obj.replace(/\$\{([^}]+)\}|\$([A-Z_][A-Z0-9_]*)/g, (match, braced, unbraced) => {
    18→      const varName = braced || unbraced;
    19→      return process.env[varName] || match; // Keep original if env var doesn't exist
    20→    });
    21→  } else if (Array.isArray(obj)) {
    22→    return obj.map(interpolateEnvVars);
    23→  } else if (obj !== null && typeof obj === "object") {
    24→    const result: any = {};
    25→    for (const [key, value] of Object.entries(obj)) {
    26→      result[key] = interpolateEnvVars(value);
    27→    }
    28→    return result;
    29→  }
    30→  return obj;
    31→};
