   126→export const backupConfigFile = async () => {
   127→  try {
   128→    if (await fs.access(CONFIG_FILE).then(() => true).catch(() => false)) {
   129→      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
   130→      const backupPath = `${CONFIG_FILE}.${timestamp}.bak`;
   131→      await fs.copyFile(CONFIG_FILE, backupPath);
   132→
   133→      // Clean up old backups, keeping only the 3 most recent
   134→      try {
   135→        const configDir = path.dirname(CONFIG_FILE);
   136→        const configFileName = path.basename(CONFIG_FILE);
   137→        const files = await fs.readdir(configDir);
   138→
   139→        // Find all backup files for this config
   140→        const backupFiles = files
   141→          .filter(file => file.startsWith(configFileName) && file.endsWith('.bak'))
   142→          .sort()
   143→          .reverse(); // Sort in descending order (newest first)
   144→
   145→        // Delete all but the 3 most recent backups
   146→        if (backupFiles.length > 3) {
   147→          for (let i = 3; i < backupFiles.length; i++) {
   148→            const oldBackupPath = path.join(configDir, backupFiles[i]);
   149→            await fs.unlink(oldBackupPath);
   150→          }
   151→        }
   152→      } catch (cleanupError) {
   153→        console.warn("Failed to clean up old backups:", cleanupError);
   154→      }
   155→
   156→      return backupPath;
   157→    }
   158→  } catch (error) {
   159→    console.error("Failed to backup config file:", error);
   160→  }
   161→  return null;
   162→};
