    16→export const calculateTokenCount = (
    17→  messages: MessageParam[],
    18→  system: any,
    19→  tools: Tool[]
    20→) => {
    21→  let tokenCount = 0;
    22→  if (Array.isArray(messages)) {
    23→    messages.forEach((message) => {
    24→      if (typeof message.content === "string") {
    25→        tokenCount += enc.encode(message.content).length;
    26→      } else if (Array.isArray(message.content)) {
    27→        message.content.forEach((contentPart: any) => {
    28→          if (contentPart.type === "text") {
    29→            tokenCount += enc.encode(contentPart.text).length;
    30→          } else if (contentPart.type === "tool_use") {
    31→            tokenCount += enc.encode(JSON.stringify(contentPart.input)).length;
    32→          } else if (contentPart.type === "tool_result") {
    33→            tokenCount += enc.encode(
    34→              typeof contentPart.content === "string"
    35→                ? contentPart.content
    36→                : JSON.stringify(contentPart.content)
    37→            ).length;
    38→          }
    39→        });
    40→      }
    41→    });
    42→  }
    43→  if (typeof system === "string") {
    44→    tokenCount += enc.encode(system).length;
    45→  } else if (Array.isArray(system)) {
    46→    system.forEach((item: any) => {
    47→      if (item.type !== "text") return;
    48→      if (typeof item.text === "string") {
    49→        tokenCount += enc.encode(item.text).length;
    50→      } else if (Array.isArray(item.text)) {
    51→        item.text.forEach((textPart: any) => {
    52→          tokenCount += enc.encode(textPart || "").length;
    53→        });
    54→      }
    55→    });
    56→  }
    57→  if (tools) {
    58→    tools.forEach((tool: Tool) => {
    59→      if (tool.description) {
    60→        tokenCount += enc.encode(tool.name + tool.description).length;
    61→      }
    62→      if (tool.input_schema) {
    63→        tokenCount += enc.encode(JSON.stringify(tool.input_schema)).length;
    64→      }
    65→    });
    66→  }
    67→  return tokenCount;
    68→};
