    80→const getProjectSpecificRouter = async (req: any) => {
    81→  // 检查是否有项目特定的配置
    82→  if (req.sessionId) {
    83→    const project = await searchProjectBySession(req.sessionId);
    84→    if (project) {
    85→      const projectConfigPath = join(HOME_DIR, project, "config.json");
    86→      const sessionConfigPath = join(
    87→        HOME_DIR,
    88→        project,
    89→        `${req.sessionId}.json`
    90→      );
    91→
    92→      // 首先尝试读取sessionConfig文件
    93→      const sessionConfig = await readConfigFile(sessionConfigPath);
    94→      if (sessionConfig && sessionConfig.Router) {
    95→        return sessionConfig.Router;
    96→      }
    97→      const projectConfig = await readConfigFile(projectConfigPath);
    98→      if (projectConfig && projectConfig.Router) {
    99→        return projectConfig.Router;
   100→      }
   101→    }
   102→  }
   103→  return undefined; // 返回undefined表示使用原始配置
   104→};
   105→
   106→const getUseModel = async (
   107→  req: any,
   108→  tokenCount: number,
   109→  config: any,
   110→  lastUsage?: Usage | undefined
   111→) => {
   112→  const projectSpecificRouter = await getProjectSpecificRouter(req);
   113→  const Router = projectSpecificRouter || config.Router;
   114→
   115→  if (req.body.model.includes(",")) {
   116→    const [provider, model] = req.body.model.split(",");
   117→    const finalProvider = config.Providers.find(
   118→      (p: any) => p.name.toLowerCase() === provider
   119→    );
   120→    const finalModel = finalProvider?.models?.find(
   121→      (m: any) => m.toLowerCase() === model
   122→    );
   123→    if (finalProvider && finalModel) {
   124→      return `${finalProvider.name},${finalModel}`;
   125→    }
   126→    return req.body.model;
   127→  }
   128→
   129→  // if tokenCount is greater than the configured threshold, use the long context model
   130→  const longContextThreshold = Router.longContextThreshold || 60000;
   131→  const lastUsageThreshold =
   132→    lastUsage &&
   133→    lastUsage.input_tokens > longContextThreshold &&
   134→    tokenCount > 20000;
   135→  const tokenCountThreshold = tokenCount > longContextThreshold;
   136→  if ((lastUsageThreshold || tokenCountThreshold) && Router.longContext) {
   137→    req.log.info(
   138→      `Using long context model due to token count: ${tokenCount}, threshold: ${longContextThreshold}`
   139→    );
   140→    return Router.longContext;
   141→  }
   142→  if (
   143→    req.body?.system?.length > 1 &&
   144→    req.body?.system[1]?.text?.startsWith("<CCR-SUBAGENT-MODEL>")
   145→  ) {
   146→    const model = req.body?.system[1].text.match(
   147→      /<CCR-SUBAGENT-MODEL>(.*?)<\/CCR-SUBAGENT-MODEL>/s
   148→    );
   149→    if (model) {
   150→      req.body.system[1].text = req.body.system[1].text.replace(
   151→        `<CCR-SUBAGENT-MODEL>${model[1]}</CCR-SUBAGENT-MODEL>`,
   152→        ""
   153→      );
   154→      return model[1];
   155→    }
   156→  }
   157→  // Use the background model for any Claude Haiku variant
   158→  if (
   159→    req.body.model?.includes("claude") &&
   160→    req.body.model?.includes("haiku") &&
   161→    config.Router.background
   162→  ) {
   163→    req.log.info(`Using background model for ${req.body.model}`);
   164→    return config.Router.background;
   165→  }
   166→  // The priority of websearch must be higher than thinking.
   167→  if (
   168→    Array.isArray(req.body.tools) &&
   169→    req.body.tools.some((tool: any) => tool.type?.startsWith("web_search")) &&
   170→    Router.webSearch
   171→  ) {
   172→    return Router.webSearch;
   173→  }
   174→  // if exits thinking, use the think model
   175→  if (req.body.thinking && Router.think) {
   176→    req.log.info(`Using think model for ${req.body.thinking}`);
   177→    return Router.think;
   178→  }
   179→  return Router!.default;
   180→};
   181→
   182→export const router = async (req: any, _res: any, context: any) => {
   183→  const { config, event } = context;
   184→  // Parse sessionId from metadata.user_id
   185→  if (req.body.metadata?.user_id) {
   186→    const parts = req.body.metadata.user_id.split("_session_");
   187→    if (parts.length > 1) {
   188→      req.sessionId = parts[1];
   189→    }
   190→  }
   191→  const lastMessageUsage = sessionUsageCache.get(req.sessionId);
   192→  const { messages, system = [], tools }: MessageCreateParamsBase = req.body;
   193→  if (
   194→    config.REWRITE_SYSTEM_PROMPT &&
   195→    system.length > 1 &&
   196→    system[1]?.text?.includes("<env>")
   197→  ) {
   198→    const prompt = await readFile(config.REWRITE_SYSTEM_PROMPT, "utf-8");
   199→    system[1].text = `${prompt}<env>${system[1].text.split("<env>").pop()}`;
   200→  }
   201→
   202→  try {
   203→    const tokenCount = calculateTokenCount(
   204→      messages as MessageParam[],
   205→      system,
   206→      tools as Tool[]
   207→    );
   208→
   209→    let model;
   210→    if (config.CUSTOM_ROUTER_PATH) {
   211→      try {
   212→        const customRouter = require(config.CUSTOM_ROUTER_PATH);
   213→        req.tokenCount = tokenCount; // Pass token count to custom router
   214→        model = await customRouter(req, config, {
   215→          event,
   216→        });
   217→      } catch (e: any) {
   218→        req.log.error(`failed to load custom router: ${e.message}`);
   219→      }
   220→    }
   221→    if (!model) {
   222→      model = await getUseModel(req, tokenCount, config, lastMessageUsage);
   223→    }
   224→    req.body.model = model;
   225→  } catch (error: any) {
   226→    req.log.error(`Error in router middleware: ${error.message}`);
   227→    req.body.model = config.Router!.default;
   228→  }
   229→  return;
   230→};
   231→
   232→// 内存缓存，存储sessionId到项目名称的映射
   233→// null值表示之前已查找过但未找到项目
   234→// 使用LRU缓存，限制最大1000个条目
   235→const sessionProjectCache = new LRUCache<string, string | null>({
   236→  max: 1000,
   237→});
   238→
   239→export const searchProjectBySession = async (
   240→  sessionId: string
   241→): Promise<string | null> => {
   242→  // 首先检查缓存
   243→  if (sessionProjectCache.has(sessionId)) {
   244→    return sessionProjectCache.get(sessionId)!;
   245→  }
   246→
   247→  try {
   248→    const dir = await opendir(CLAUDE_PROJECTS_DIR);
   249→    const folderNames: string[] = [];
   250→
   251→    // 收集所有文件夹名称
   252→    for await (const dirent of dir) {
   253→      if (dirent.isDirectory()) {
   254→        folderNames.push(dirent.name);
   255→      }
   256→    }
   257→
   258→    // 并发检查每个项目文件夹中是否存在sessionId.jsonl文件
   259→    const checkPromises = folderNames.map(async (folderName) => {
   260→      const sessionFilePath = join(
   261→        CLAUDE_PROJECTS_DIR,
   262→        folderName,
   263→        `${sessionId}.jsonl`
   264→      );
   265→      try {
   266→        const fileStat = await stat(sessionFilePath);
   267→        return fileStat.isFile() ? folderName : null;
   268→      } catch {
   269→        // 文件不存在，继续检查下一个
   270→        return null;
   271→      }
   272→    });
   273→
   274→    const results = await Promise.all(checkPromises);
   275→
   276→    // 返回第一个存在的项目目录名称
   277→    for (const result of results) {
   278→      if (result) {
   279→        // 缓存找到的结果
   280→        sessionProjectCache.set(sessionId, result);
   281→        return result;
   282→      }
   283→    }
   284→
   285→    // 缓存未找到的结果（null值表示之前已查找过但未找到项目）
   286→    sessionProjectCache.set(sessionId, null);
   287→    return null; // 没有找到匹配的项目
   288→  } catch (error) {
   289→    console.error("Error searching for project by session:", error);
   290→    // 出错时也缓存null结果，避免重复出错
   291→    sessionProjectCache.set(sessionId, null);
   292→    return null;
   293→  }
   294→};
