     1→import { FastifyRequest, FastifyReply } from "fastify";
     2→
     3→export const apiKeyAuth =
     4→  (config: any) =>
     5→  async (req: FastifyRequest, reply: FastifyReply, done: () => void) => {
     6→    // Public endpoints that don't require authentication
     7→    if (["/", "/health"].includes(req.url) || req.url.startsWith("/ui")) {
     8→      return done();
     9→    }
    10→
    11→    const apiKey = config.APIKEY;
    12→    if (!apiKey) {
    13→      // If no API key is set, enable CORS for local
    14→      const allowedOrigins = [
    15→        `http://127.0.0.1:${config.PORT || 3456}`,
    16→        `http://localhost:${config.PORT || 3456}`,
    17→      ];
    18→      if (req.headers.origin && !allowedOrigins.includes(req.headers.origin)) {
    19→        reply.status(403).send("CORS not allowed for this origin");
    20→        return;
    21→      } else {
    22→        reply.header('Access-Control-Allow-Origin', `http://127.0.0.1:${config.PORT || 3456}`);
    23→        reply.header('Access-Control-Allow-Origin', `http://localhost:${config.PORT || 3456}`);
    24→      }
    25→      return done();
    26→    }
    27→
    28→    const authHeaderValue =
    29→      req.headers.authorization || req.headers["x-api-key"];
    30→    const authKey: string = Array.isArray(authHeaderValue)
    31→      ? authHeaderValue[0]
    32→      : authHeaderValue || "";
    33→    if (!authKey) {
    34→      reply.status(401).send("APIKEY is missing");
    35→      return;
    36→    }
    37→    let token = "";
    38→    if (authKey.startsWith("Bearer")) {
    39→      token = authKey.split(" ")[1];
    40→    } else {
    41→      token = authKey;
    42→    }
    43→
    44→    if (token !== apiKey) {
    45→      reply.status(401).send("Invalid API key");
    46→      return;
    47→    }
    48→
    49→    done();
    50→  };
    51→

