   179→async function configureTransformers(): Promise<TransformerConfig | undefined> {
   180→  const useTransformers = await confirm({
   181→    message: `\n${BOLDYELLOW}Add transformer configuration?${RESET}`,
   182→    default: false
   183→  });
   184→  
   185→  if (!useTransformers) {
   186→    return undefined;
   187→  }
   188→  
   189→  const transformers: Array<string | [string, any]> = [];
   190→  let addMore = true;
   191→  
   192→  while (addMore) {
   193→    const transformer = await select({
   194→      message: `\n${BOLDYELLOW}Select a transformer:${RESET}`,
   195→      choices: AVAILABLE_TRANSFORMERS.map(t => ({ name: t, value: t })),
   196→      pageSize: 15
   197→    }) as string;
   198→    
   199→    // Check if transformer needs options
   200→    if (transformer === 'maxtoken') {
   201→      const maxTokens = await input({
   202→        message: `\n${BOLDYELLOW}Max tokens:${RESET}`,
   203→        default: '30000',
   204→        validate: (value: string) => {
   205→          const num = parseInt(value);
   206→          if (isNaN(num) || num <= 0) {
   207→            return 'Please enter a valid positive number';
   208→          }
   209→          return true;
   210→        }
   211→      });
   212→      transformers.push(['maxtoken', { max_tokens: parseInt(maxTokens) }]);
   213→    } else if (transformer === 'openrouter') {
   214→      const addProvider = await confirm({
   215→        message: `\n${BOLDYELLOW}Add provider routing options?${RESET}`,
   216→        default: false
   217→      });
   218→      
   219→      if (addProvider) {
   220→        const providerInput = await input({
   221→          message: 'Provider (e.g., moonshotai/fp8):',
   222→          validate: (value: string) => value.trim() !== '' || 'Provider cannot be empty'
   223→        });
   224→        transformers.push(['openrouter', { provider: { only: [providerInput] } }]);
   225→      } else {
   226→        transformers.push(transformer);
   227→      }
   228→    } else {
   229→      transformers.push(transformer);
   230→    }
   231→    
   232→    addMore = await confirm({
   233→      message: `\n${BOLDYELLOW}Add another transformer?${RESET}`,
   234→      default: false
   235→    });
   236→  }
   237→  
   238→  return { use: transformers };
   239→}
