   261→async function addModelToExistingProvider(config: Config, providerName: string): Promise<ModelResult | null> {
   262→  const modelName = await input({
   263→    message: `\n${BOLDYELLOW}Enter the model name:${RESET}`,
   264→    validate: (value: string) => {
   265→      if (!value.trim()) {
   266→        return 'Model name cannot be empty';
   267→      }
   268→      return true;
   269→    }
   270→  });
   271→  
   272→  const provider = config.Providers.find(p => p.name === providerName);
   273→  
   274→  if (!provider) {
   275→    console.log(`${YELLOW}Provider not found${RESET}`);
   276→    return null;
   277→  }
   278→  
   279→  if (provider.models.includes(modelName)) {
   280→    console.log(`${YELLOW}Model already exists in provider${RESET}`);
   281→    return null;
   282→  }
   283→  
   284→  provider.models.push(modelName);
   285→  
   286→  // Ask about model-specific transformers
   287→  const addModelTransformer = await confirm({
   288→    message: `\n${BOLDYELLOW}Add model-specific transformer configuration?${RESET}`,
   289→    default: false
   290→  });
   291→  
   292→  if (addModelTransformer) {
   293→    const transformerConfig = await configureTransformers();
   294→    if (transformerConfig && provider.transformer) {
   295→      provider.transformer[modelName] = transformerConfig;
   296→    }
   297→  }
   298→  
   299→  saveConfig(config);
   300→  
   301→  console.log(`${GREEN}✓ Model "${modelName}" added to provider "${providerName}"${RESET}`);
   302→  
   303→  const setAsDefault = await confirm({
   304→    message: `\n${BOLDYELLOW}Do you want to set this model in router configuration?${RESET}`,
   305→    default: false
   306→  });
   307→  
   308→  if (setAsDefault) {
   309→    const modelType = await select({
   310→      message: `\n${BOLDYELLOW}Select configuration type:${RESET}`,
   311→      choices: [
   312→        { name: 'Default Model', value: 'default' },
   313→        { name: 'Background Model', value: 'background' },
   314→        { name: 'Think Model', value: 'think' },
   315→        { name: 'Long Context Model', value: 'longContext' },
   316→        { name: 'Web Search Model', value: 'webSearch' },
   317→        { name: 'Image Model', value: 'image' }
   318→      ]
   319→    }) as string;
   320→    
   321→    return { providerName, modelName, modelType };
   322→  }
   323→  
   324→  return null;
   325→}
