   327→async function addNewProvider(config: Config): Promise<ModelResult | null> {
   328→  console.log(`\n${BOLDCYAN}Adding New Provider${RESET}\n`);
   329→  
   330→  const providerName = await input({
   331→    message: `${BOLDYELLOW}Provider name:${RESET}`,
   332→    validate: (value: string) => {
   333→      if (!value.trim()) {
   334→        return 'Provider name cannot be empty';
   335→      }
   336→      if (config.Providers.some(p => p.name === value)) {
   337→        return 'Provider already exists';
   338→      }
   339→      return true;
   340→    }
   341→  });
   342→  
   343→  const apiBaseUrl = await input({
   344→    message: `\n${BOLDYELLOW}API base URL:${RESET}`,
   345→    validate: (value: string) => {
   346→      if (!value.trim()) {
   347→        return 'API base URL cannot be empty';
   348→      }
   349→      try {
   350→        new URL(value);
   351→        return true;
   352→      } catch {
   353→        return 'Please enter a valid URL';
   354→      }
   355→    }
   356→  });
   357→  
   358→  const apiKey = await input({
   359→    message: `\n${BOLDYELLOW}API key:${RESET}`,
   360→    validate: (value: string) => {
   361→      if (!value.trim()) {
   362→        return 'API key cannot be empty';
   363→      }
   364→      return true;
   365→    }
   366→  });
   367→  
   368→  const modelsInput = await input({
   369→    message: `\n${BOLDYELLOW}Model names (comma-separated):${RESET}`,
   370→    validate: (value: string) => {
   371→      if (!value.trim()) {
   372→        return 'At least one model name is required';
   373→      }
   374→      return true;
   375→    }
   376→  });
   377→  
   378→  const models = modelsInput.split(',').map(m => m.trim()).filter(m => m);
   379→  
   380→  const newProvider: Provider = {
   381→    name: providerName,
   382→    api_base_url: apiBaseUrl,
   383→    api_key: apiKey,
   384→    models: models
   385→  };
   386→  
   387→  // Global transformer configuration
   388→  const transformerConfig = await configureTransformers();
   389→  if (transformerConfig) {
   390→    newProvider.transformer = transformerConfig;
   391→  }
   392→  
   393→  config.Providers.push(newProvider);
   394→  saveConfig(config);
   395→  
   396→  console.log(`${GREEN}\n✓ Provider "${providerName}" added successfully${RESET}`);
   397→  
   398→  const setAsDefault = await confirm({
   399→    message: `\n${BOLDYELLOW}Do you want to set one of these models in router configuration?${RESET}`,
   400→    default: false
   401→  });
   402→  
   403→  if (setAsDefault && models.length > 0) {
   404→    let selectedModel = models[0];
   405→    
   406→    if (models.length > 1) {
   407→      selectedModel = await select({
   408→        message: `\n${BOLDYELLOW}Select which model to configure:${RESET}`,
   409→        choices: models.map(m => ({ name: m, value: m }))
   410→      }) as string;
   411→    }
   412→    
   413→    const modelType = await select({
   414→      message: `\n${BOLDYELLOW}Select configuration type:${RESET}`,
   415→      choices: [
   416→        { name: 'Default Model', value: 'default' },
   417→        { name: 'Background Model', value: 'background' },
   418→        { name: 'Think Model', value: 'think' },
   419→        { name: 'Long Context Model', value: 'longContext' },
   420→        { name: 'Web Search Model', value: 'webSearch' },
   421→        { name: 'Image Model', value: 'image' }
   422→      ]
   423→    }) as string;
   424→    
   425→    return { providerName, modelName: selectedModel, modelType };
   426→  }
   427→  
   428→  return null;
   429→}
