   433→  
   434→  try {
   435→    let config = loadConfig();
   436→    displayCurrentConfig(config);
   437→    
   438→    const action = await selectModelType() as string;
   439→    
   440→    if (action === 'addModel') {
   441→      const result = await addNewModel(config);
   442→      
   443→      if (result) {
