    13→export async function executeCodeCommand(args: string[] = []) {
    14→  // Set environment variables using shared function
    15→  const config = await readConfigFile();
    16→  const env = await createEnvVariables();
    17→  const settingsFlag = {
    18→    env
    19→  };
    20→  if (config?.StatusLine?.enabled) {
    21→    settingsFlag.statusLine = {
    22→      type: "command",
    23→      command: "ccr statusline",
    24→      padding: 0,
    25→    }
    26→  }
    27→  args.push('--settings', `${JSON.stringify(settingsFlag)}`);
    28→
    29→  // Non-interactive mode for automation environments
    30→  if (config.NON_INTERACTIVE_MODE) {
    31→    env.CI = "true";
    32→    env.FORCE_COLOR = "0";
    33→    env.NODE_NO_READLINE = "1";
    34→    env.TERM = "dumb";
    35→  }
    36→
    37→  // Set ANTHROPIC_SMALL_FAST_MODEL if it exists in config
    38→  if (config?.ANTHROPIC_SMALL_FAST_MODEL) {
    39→    env.ANTHROPIC_SMALL_FAST_MODEL = config.ANTHROPIC_SMALL_FAST_MODEL;
    40→  }
    41→
    42→  // Increment reference count when command starts
    43→  incrementReferenceCount();
    44→
    45→  // Execute claude command
    46→  const claudePath = config?.CLAUDE_PATH || process.env.CLAUDE_PATH || "claude";
    47→
    48→  const joinedArgs = args.length > 0 ? quote(args) : "";
    49→
    50→  const stdioConfig: StdioOptions = config.NON_INTERACTIVE_MODE
    51→    ? ["pipe", "inherit", "inherit"] // Pipe stdin for non-interactive
    52→    : "inherit"; // Default inherited behavior
    53→
    54→  const argsObj = minimist(args)
    55→  const argsArr = []
    56→  for (const [argsObjKey, argsObjValue] of Object.entries(argsObj)) {
    57→    if (argsObjKey !== '_' && argsObj[argsObjKey]) {
    58→      const prefix = argsObjKey.length === 1 ? '-' : '--';
    59→      // For boolean flags, don't append the value
    60→      if (argsObjValue === true) {
    61→        argsArr.push(`${prefix}${argsObjKey}`);
    62→      } else {
    63→        argsArr.push(`${prefix}${argsObjKey} ${JSON.stringify(argsObjValue)}`);
    64→      }
    65→    }
    66→  }
    67→  const claudeProcess = spawn(
    68→    claudePath,
    69→    argsArr,
    70→    {
    71→      env: process.env,
    72→      stdio: stdioConfig,
    73→      shell: true,
    74→    }
    75→  );
    76→
    77→  // Close stdin for non-interactive mode
    78→  if (config.NON_INTERACTIVE_MODE) {
    79→    claudeProcess.stdin?.end();
    80→  }
    81→
    82→  claudeProcess.on("error", (error) => {
    83→    console.error("Failed to start claude command:", error.message);
    84→    console.log(
    85→      "Make sure Claude Code is installed: npm install -g @anthropic-ai/claude-code"
    86→    );
    87→    decrementReferenceCount();
    88→    process.exit(1);
    89→  });
    90→
    91→  claudeProcess.on("close", (code) => {
    92→    decrementReferenceCount();
    93→    closeService();
    94→    process.exit(code || 0);
    95→  });
    96→}
